1	import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
2	import {
3	  objectiveRules,
4	  presetRubbings,
5	  presetRubbingTypes,
6	  rubbingTypeOrder,
7	  sourceId,
8	  validateObjectiveRules,
9	  validateSourceAssignment,
10	  validateSourceSites,
11	  type ObjectiveRules,
12	  type RubbingType,
13	  type SourceAssignment,
14	  type SourceSite,
15	} from "@pirate-sea-race/content/objectives";
16	import { nextInt } from "../random.js";
17	
18	/** An integer sub-unit position supplied by the caller; the ledger does not know the map. */
19	export interface Position {
20	  readonly x: number;
21	  readonly y: number;
22	}
23	
24	/**
25	 * The one place a rubbing is (§4): sealed at its source, owned by a player, held in a recovery cache, or reserved for
26	 * one of the two players inside an unresolved duel.
27	 */
28	export type RubbingLocation =
29	  | { readonly kind: "source"; readonly sourceId: string }
30	  | { readonly kind: "player"; readonly playerId: string }
31	  | { readonly kind: "cache"; readonly cacheId: string }
32	  | { readonly kind: "duel"; readonly duelId: string; readonly playerId: string };
33	
34	/** §16's rubbing: its id and type never change; `revision` counts the moves it has made. */
35	export interface LedgerRubbing {
36	  readonly id: string;
37	  readonly type: RubbingType;
38	  readonly location: RubbingLocation;
39	  readonly revision: number;
40	}
41	
42	/** A source and the rubbing sealed there at the start. It is empty once that rubbing has left; nothing respawns. */
43	export interface LedgerSource {
44	  readonly id: string;
45	  readonly island: number;
46	  readonly x: number;
47	  readonly y: number;
48	  readonly type: RubbingType;
49	  readonly rubbingId: string;
50	  /** Sources start locked; the ruin that guards one unlocks it. */
51	  readonly unlocked: boolean;
52	}
53	
54	/** A held interaction: `heldTicks` counts consecutive ticks of holding since `startTick`. */
55	export type LedgerChannel =
56	  | {
57	      readonly kind: "collect";
58	      readonly sourceId: string;
59	      readonly rubbingId: string;
60	      readonly startTick: number;
61	      readonly lastTick: number;
62	      readonly heldTicks: number;
63	    }
64	  | {
65	      readonly kind: "claim";
66	      readonly cacheId: string;
67	      readonly rubbingId: string;
68	      readonly startTick: number;
69	      readonly lastTick: number;
70	      readonly heldTicks: number;
71	    };
72	
73	export type PlayerStatus = "connected" | "disconnected" | "left";
74	
75	export interface LedgerPlayer {
76	  readonly id: string;
77	  readonly gold: number;
78	  readonly status: PlayerStatus;
79	  /** While disconnected: the tick at which the seat reservation expires. Reconnecting never moves it. */
80	  readonly reservationDeadline: number | null;
81	  /** Once left: where rubbings still reserved in an unresolved duel go when that duel settles. */
82	  readonly exit: Position | null;
83	  readonly channel: LedgerChannel | null;
84	  /** Types this player lost and is owed a fresh rumor for (§11), in type order. The rumor system reads it. */
85	  readonly freshRumors: readonly RubbingType[];
86	}
87	
88	/** A recovery cache (§12). It never despawns; it disappears once empty. Its contents are the rubbings located in it. */
89	export interface LedgerCache {
90	  readonly id: string;
91	  readonly x: number;
92	  readonly y: number;
93	  readonly createdTick: number;
94	}
95	
96	/** `fighting` until the result arrives; `choosing` while the winner picks a type; `settled` once committed. */
97	export type DuelPhase = "fighting" | "choosing" | "settled";
98	
99	export interface DuelResultRecord {
100	  readonly outcome: "win" | "draw" | "cancelled";
101	  readonly winner: string | null;
102	  readonly loser: string | null;
103	  /** Decided by leaving the match (quit or reservation expiry) during the fight: the loser for a win, both players for a cancellation. */
104	  readonly forfeit: boolean;
105	  readonly tick: number;
106	}
107	
108	/** What the commit did. It happens once per duel. */
109	export interface DuelSettlement {
110	  readonly tick: number;
111	  readonly stolenRubbingId: string | null;
112	  readonly stolenType: RubbingType | null;
113	  /** Who picked the stolen type: the winner, the default at the deadline, or nobody (nothing moved). */
114	  readonly choice: "winner" | "default" | "none";
115	  readonly gold: number;
116	  readonly goldSuppressed: boolean;
117	}
118	
119	export interface LedgerDuel {
120	  readonly id: string;
121	  readonly players: readonly [string, string];
122	  readonly startTick: number;
123	  readonly phase: DuelPhase;
124	  readonly result: DuelResultRecord | null;
125	  /** In `choosing`: the first tick at which the winner can no longer choose and the default applies. */
126	  readonly choiceDeadline: number | null;
127	  readonly settlement: DuelSettlement | null;
128	}
129	
130	/** The last win of `winner` over `loser`, for §11's repeated-victory gold suppression. */
131	export interface WinRecord {
132	  readonly winner: string;
133	  readonly loser: string;
134	  readonly tick: number;
135	}
136	
137	/** The whole ledger: plain, integer data that `hashState` covers entirely. */
138	export interface LedgerState {
139	  readonly preset: RulesPresetId;
140	  readonly rules: ObjectiveRules;
141	  /** The preset's types, in the fixed type order. */
142	  readonly types: readonly RubbingType[];
143	  /** The latest world tick an applied request carried. Requests from earlier ticks are stale. */
144	  readonly tick: number;
145	  readonly rng: number;
146	  readonly sources: readonly LedgerSource[];
147	  /** Every rubbing of the preset, by id. */
148	  readonly rubbings: readonly LedgerRubbing[];
149	  /** In join order; a player who left stays, with status `left`. */
150	  readonly players: readonly LedgerPlayer[];
151	  readonly caches: readonly LedgerCache[];
152	  /** In reservation order, settled ones included, so a repeated message finds its result. */
153	  readonly duels: readonly LedgerDuel[];
154	  readonly wins: readonly WinRecord[];
155	  readonly nextCacheNumber: number;
156	  /** Gold players brought in when joining. Settlements only move gold, so the balances always sum to this. */
157	  readonly goldIssued: number;
158	}
159	
160	/**
161	 * Deals the preset's rubbings onto the sites with the seeded generator: a Fisher–Yates shuffle, so the server alone
162	 * decides, and the same seed and sites always give the same assignment. Source ids number each island's sites in the
163	 * order given.
164	 */
165	export function assignSources(
166	  presetId: RulesPresetId,
167	  sites: readonly SourceSite[],
168	  seed: number,
169	): { assignment: SourceAssignment; rng: number } {
170	  if (!Number.isInteger(seed)) throw new RangeError(`seed must be an integer, got ${seed}`);
171	  const preset = rulesPresets[presetId];
172	  const checked = validateSourceSites(preset, sites);
173	  if (!checked.ok) throw new Error(`invalid source sites for ${presetId}: ${checked.issues.join("; ")}`);
174	  const deck = presetRubbings(preset);
175	  let rng = seed >>> 0;
176	  for (let index = deck.length - 1; index > 0; index--) {
177	    const drawn = nextInt(rng, index + 1);
178	    rng = drawn.state;
179	    [deck[index], deck[drawn.value]] = [deck[drawn.value]!, deck[index]!];
180	  }
181	  const slots = new Map<number, number>();
182	  const sources = checked.value.map((site, index) => {
183	    const slot = slots.get(site.island) ?? 0;
184	    slots.set(site.island, slot + 1);
185	    const rubbing = deck[index]!;
186	    return { id: sourceId(site.island, slot), island: site.island, x: site.x, y: site.y, type: rubbing.type, rubbingId: rubbing.id };
187	  });
188	  const assignment = validateSourceAssignment({ preset: presetId, seed: seed >>> 0, sources });
189	  if (!assignment.ok) throw new Error(`invalid source assignment: ${assignment.issues.join("; ")}`);
190	  return { assignment: assignment.value, rng };
191	}
192	
193	export interface CreateLedgerOptions {
194	  readonly preset: RulesPresetId;
195	  readonly seed: number;
196	  readonly sites: readonly SourceSite[];
197	  readonly rules?: ObjectiveRules;
198	}
199	
200	/** A new match's ledger: every rubbing sealed at its (locked) source, no players, caches or duels. */
201	export function createLedger(options: CreateLedgerOptions): LedgerState {
202	  const rules = validateObjectiveRules(options.rules ?? objectiveRules);
203	  if (!rules.ok) throw new Error(`invalid objective rules: ${rules.issues.join("; ")}`);
204	  const { assignment, rng } = assignSources(options.preset, options.sites, options.seed);
205	  return createLedgerFromAssignment(assignment, rng, rules.value);
206	}
207	
208	/** A ledger from an assignment made earlier (validated again here), for example one restored from a match record. */
209	export function createLedgerFromAssignment(
210	  candidate: SourceAssignment,
211	  rng: number,
212	  rules: ObjectiveRules = objectiveRules,
213	): LedgerState {
214	  const parsed = validateSourceAssignment(candidate);
215	  if (!parsed.ok) throw new Error(`invalid source assignment: ${parsed.issues.join("; ")}`);
216	  const checkedRules = validateObjectiveRules(rules);
217	  if (!checkedRules.ok) throw new Error(`invalid objective rules: ${checkedRules.issues.join("; ")}`);
218	  const assignment = parsed.value;
219	  const sources: LedgerSource[] = assignment.sources.map((source) => ({ ...source, unlocked: false }));
220	  const rubbings: LedgerRubbing[] = sources
221	    .map((source) => ({
222	      id: source.rubbingId,
223	      type: source.type,
224	      location: { kind: "source", sourceId: source.id } as const,
225	      revision: 0,
226	    }))
227	    .sort(byId);
228	  return {
229	    preset: assignment.preset,
230	    rules: checkedRules.value,
231	    types: presetRubbingTypes(rulesPresets[assignment.preset]),
232	    tick: 0,
233	    rng: rng >>> 0,
234	    sources,
235	    rubbings,
236	    players: [],
237	    caches: [],
238	    duels: [],
239	    wins: [],
240	    nextCacheNumber: 1,
241	    goldIssued: 0,
242	  };
243	}
244	
245	export function byId<T extends { readonly id: string }>(a: T, b: T): number {
246	  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
247	}
248	
249	export function byTypeOrder(a: RubbingType, b: RubbingType): number {
250	  return rubbingTypeOrder(a) - rubbingTypeOrder(b);
251	}
252	
253	export function findPlayer(state: LedgerState, id: string): LedgerPlayer | undefined {
254	  return state.players.find((player) => player.id === id);
255	}
256	
257	export function findSource(state: LedgerState, id: string): LedgerSource | undefined {
258	  return state.sources.find((source) => source.id === id);
259	}
260	
261	export function findCache(state: LedgerState, id: string): LedgerCache | undefined {
262	  return state.caches.find((cache) => cache.id === id);
263	}
264	
265	export function findDuel(state: LedgerState, id: string): LedgerDuel | undefined {
266	  return state.duels.find((duel) => duel.id === id);
267	}
268	
269	export function findRubbing(state: LedgerState, id: string): LedgerRubbing | undefined {
270	  return state.rubbings.find((rubbing) => rubbing.id === id);
271	}
272	
273	/** A player's rubbings: those they own and those reserved for them in an unresolved duel. */
274	export function heldRubbings(state: LedgerState, playerId: string): LedgerRubbing[] {
275	  return state.rubbings.filter(
276	    (rubbing) =>
277	      (rubbing.location.kind === "player" || rubbing.location.kind === "duel") && rubbing.location.playerId === playerId,
278	  );
279	}
280	
281	export function heldTypes(state: LedgerState, playerId: string): RubbingType[] {
282	  return heldRubbings(state, playerId)
283	    .map((rubbing) => rubbing.type)
284	    .sort(byTypeOrder);
285	}
286	
287	/** The input §5's claim rules take: the player holds every type of the preset. */
288	export function holdsAllTypes(state: LedgerState, playerId: string): boolean {
289	  const held = new Set(heldTypes(state, playerId));
290	  return state.types.every((type) => held.has(type));
291	}
292	
293	export function cacheRubbings(state: LedgerState, cacheId: string): LedgerRubbing[] {
294	  return state.rubbings.filter((rubbing) => rubbing.location.kind === "cache" && rubbing.location.cacheId === cacheId);
295	}
296	
297	/** Sources of a type whose rubbing is still sealed there (locked or not). */
298	export function freeSourceCount(state: LedgerState, type: RubbingType): number {
299	  return state.rubbings.filter((rubbing) => rubbing.type === type && rubbing.location.kind === "source").length;
300	}
301	
302	/** The duel a player is in that has not settled yet, if any. */
303	export function activeDuelOf(state: LedgerState, playerId: string): LedgerDuel | undefined {
304	  return state.duels.find((duel) => duel.phase !== "settled" && duel.players.includes(playerId));
305	}
306	
307	export function reservedIn(state: LedgerState, duelId: string, playerId: string): LedgerRubbing[] {
308	  return state.rubbings.filter(
309	    (rubbing) => rubbing.location.kind === "duel" && rubbing.location.duelId === duelId && rubbing.location.playerId === playerId,
310	  );
311	}
312	
313	/**
314	 * The types the winner of a decided duel may steal (§4): held by the loser, lacked by the winner. None once the
315	 * winner has left the match, and none for a draw.
316	 */
317	export function eligibleTheftTypes(state: LedgerState, duelId: string): RubbingType[] {
318	  const duel = findDuel(state, duelId);
319	  if (!duel || duel.phase === "settled" || duel.result?.outcome !== "win") return [];
320	  const { winner, loser } = duel.result;
321	  if (winner === null || loser === null || findPlayer(state, winner)?.status === "left") return [];
322	  const winnerTypes = new Set(heldTypes(state, winner));
323	  return heldTypes(state, loser).filter((type) => !winnerTypes.has(type));
324	}
325	
326	/** §4's default theft: the eligible type with the fewest free sources, then the fixed type order. */
327	export function defaultTheftType(state: LedgerState, eligible: readonly RubbingType[]): RubbingType | null {
328	  let best: RubbingType | null = null;
329	  let bestFree = 0;
330	  for (const type of [...eligible].sort(byTypeOrder)) {
331	    const free = freeSourceCount(state, type);
332	    if (best === null || free < bestFree) {
333	      best = type;
334	      bestFree = free;
335	    }
336	  }
337	  return best;
338	}
339

