1	import {
2	  findPlayer,
3	  type LedgerCache,
4	  type LedgerPlayer,
5	  type LedgerRubbing,
6	  type LedgerState,
7	  type Position,
8	  type RubbingLocation,
9	} from "./state.js";
10	
11	/**
12	 * Why a request changed nothing (§16: duplicate, stale, unauthorised or already-resolved requests return the current
13	 * result without mutating state). A rejected request always returns the very state object it was given.
14	 */
15	export type LedgerRejection =
16	  | "invalid-request"
17	  | "stale-tick"
18	  | "duplicate"
19	  | "unknown-player"
20	  | "player-left"
21	  | "player-disconnected"
22	  | "player-in-duel"
23	  | "same-player"
24	  | "unknown-source"
25	  | "source-locked"
26	  | "source-empty"
27	  | "type-held"
28	  | "unknown-cache"
29	  | "not-in-cache"
30	  | "no-channel"
31	  | "unknown-duel"
32	  | "not-a-participant"
33	  | "already-resolved"
34	  | "not-choosing"
35	  | "not-winner"
36	  | "choice-window-closed"
37	  | "ineligible-type"
38	  | "not-disconnected"
39	  | "reservation-active"
40	  | "reservation-expired";
41	
42	/** One rubbing move, for §16's transfer record. `revisionAfter` is always `revisionBefore + 1`. */
43	export interface Transfer {
44	  readonly rubbingId: string;
45	  readonly from: RubbingLocation;
46	  readonly to: RubbingLocation;
47	  readonly revisionBefore: number;
48	  readonly revisionAfter: number;
49	}
50	
51	/** What every operation returns: the next state (the same object when nothing changed) and its result. */
52	export interface LedgerStep<R> {
53	  readonly state: LedgerState;
54	  readonly result: R;
55	}
56	
57	/** Moves made so far by one operation, and the caches it opened. */
58	export interface Effects {
59	  readonly transfers: Transfer[];
60	  readonly cacheIds: string[];
61	}
62	
63	export function noEffects(): Effects {
64	  return { transfers: [], cacheIds: [] };
65	}
66	
67	function isSafeInteger(value: unknown): value is number {
68	  return typeof value === "number" && Number.isSafeInteger(value);
69	}
70	
71	export function isPlayerId(value: unknown): value is string {
72	  return typeof value === "string" && value.length > 0;
73	}
74	
75	export function isPosition(value: unknown): value is Position {
76	  if (typeof value !== "object" || value === null) return false;
77	  const { x, y } = value as Record<string, unknown>;
78	  return isSafeInteger(x) && isSafeInteger(y);
79	}
80	
81	/** A request's tick must be a non-negative integer no earlier than the ledger's latest. */
82	export function tickRejection(state: LedgerState, tick: unknown): LedgerRejection | null {
83	  if (!isSafeInteger(tick) || tick < 0) return "invalid-request";
84	  return tick < state.tick ? "stale-tick" : null;
85	}
86	
87	export function atTick(state: LedgerState, tick: number): LedgerState {
88	  return tick === state.tick ? state : { ...state, tick };
89	}
90	
91	/** Why a player cannot act in the world right now, if they cannot. */
92	export function playerRejection(state: LedgerState, playerId: unknown): LedgerRejection | null {
93	  if (!isPlayerId(playerId)) return "invalid-request";
94	  const player = findPlayer(state, playerId);
95	  if (!player) return "unknown-player";
96	  return player.status === "left" ? "player-left" : null;
97	}
98	
99	export function updatePlayer(
100	  state: LedgerState,
101	  playerId: string,
102	  update: (player: LedgerPlayer) => LedgerPlayer,
103	): LedgerState {
104	  return { ...state, players: state.players.map((player) => (player.id === playerId ? update(player) : player)) };
105	}
106	
107	/** Moves each listed rubbing to its target, bumping its revision, and drops any cache the moves emptied. */
108	export function moveRubbings(
109	  state: LedgerState,
110	  moves: readonly { readonly rubbingId: string; readonly to: RubbingLocation }[],
111	  effects: Effects,
112	): LedgerState {
