1	import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
2	import { describe, expect, it } from "vitest";
3	import { nextInt } from "../random.js";
4	import {
5	  activeDuelOf,
6	  addPlayer,
7	  advanceLedger,
8	  cacheRubbings,
9	  cancelChannel,
10	  checkLedger,
11	  chooseTheft,
12	  createLedger,
13	  disconnectPlayer,
14	  eligibleTheftTypes,
15	  expireReservation,
16	  findPlayer,
17	  findRubbing,
18	  hashState,
19	  heldTypes,
20	  progressChannel,
21	  quitPlayer,
22	  reconnectPlayer,
23	  reportDuelResult,
24	  reserveDuel,
25	  startCacheClaim,
26	  startCollect,
27	  unlockSource,
28	  type LedgerState,
29	  type LedgerStep,
30	  type Transfer,
31	} from "./index.js";
32	
33	/** Freezes a state deeply, so any operation that writes into its input throws. */
34	function deepFreeze<T>(value: T): T {
35	  if (typeof value !== "object" || value === null || Object.isFrozen(value)) return value;
36	  for (const child of Object.values(value)) deepFreeze(child);
37	  return Object.freeze(value);
38	}
39	
40	/** The test's own seeded generator, apart from the ledger's. */
41	class Dice {
42	  constructor(private state: number) {}
43	  int(bound: number): number {
44	    const drawn = nextInt(this.state, bound);
45	    this.state = drawn.state;
46	    return drawn.value;
47	  }
48	  pick<T>(items: readonly T[]): T {
49	    return items[this.int(items.length)]!;
50	  }
51	  percent(chance: number): boolean {
52	    return this.int(1000) < chance * 10;
53	  }
54	}
55	
56	type Stats = Record<string, number>;
57	
58	interface Outcome {
59	  readonly ok: boolean;
60	  readonly rejection: string | null;
61	  readonly transfers?: readonly Transfer[];
62	  readonly status?: string | null;
63	  readonly cacheIds?: readonly string[];
64	}
65	
66	/**
67	 * A seeded random match: players join, collect, get interrupted, duel (won, lost, drawn, cancelled), choose or let
68	 * the window lapse, repeat old messages, disconnect, return, expire, quit and claim from caches, mixed with invalid,
69	 * duplicate and stale requests. After every operation the invariant holds, a rejected request returned its input
70	 * state, and every reported transfer matches where the rubbing now is.
71	 */
72	function simulate(preset: RulesPresetId, seed: number, steps: number, check = true): { state: LedgerState; stats: Stats } {
73	  const dice = new Dice(seed ^ 0x5eed);
74	  const { islands, sourcesPerIsland, maxPlayers } = rulesPresets[preset];
75	  const sites = Array.from({ length: islands * sourcesPerIsland }, (_, index) => ({
76	    island: Math.floor(index / sourcesPerIsland),
77	    x: dice.int(50_000),
78	    y: dice.int(50_000),
79	  }));
80	  let state = deepFreeze(createLedger({ preset, seed, sites }));
81	  const stats: Stats = {};
82	  const count = (key: string) => (stats[key] = (stats[key] ?? 0) + 1);
83	  let now = 0;
84	  let joined = 0;
85	  let duelNumber = 0;
86	  const messages: (() => LedgerStep<Outcome>)[] = [];
87	
88	  const apply = <Q, R extends Outcome>(label: string, op: (s: LedgerState, q: Q) => LedgerStep<R>, request: Q): R => {
89	    const before = state;
90	    const { state: after, result } = op(before, request);
91	    count("operations");
92	    count(`${label}:${result.ok ? "ok" : result.rejection}`);
93	    if (result.status) count(`status:${result.status}`);
94	    if (!check) {
95	      state = after;
96	      return result;
97	    }
98	    const problems = checkLedger(after);
99	    if (problems.length > 0) throw new Error(`seed ${seed}, ${label} ${JSON.stringify(request)}:\n${problems.join("\n")}`);
100	    if (!result.ok && after !== before) throw new Error(`${label} was rejected (${result.rejection}) but changed the state`);
101	    const moved = new Set<string>();
102	    for (const transfer of result.transfers ?? []) {
103	      if (moved.has(transfer.rubbingId)) throw new Error(`${label} moved ${transfer.rubbingId} twice`);
104	      moved.add(transfer.rubbingId);
105	      const rubbing = findRubbing(after, transfer.rubbingId)!;
106	      expect(rubbing.location).toEqual(transfer.to);
107	      expect(rubbing.revision).toBe(transfer.revisionAfter);
108	      expect(transfer.revisionAfter).toBe(transfer.revisionBefore + 1);
109	      expect(findRubbing(before, transfer.rubbingId)!.location).toEqual(transfer.from);
110	    }
111	    state = deepFreeze(after);
112	    return result;
113	  };
114	
115	  const players = () => state.players.map((player) => player.id);
116	  const present = () => state.players.filter((player) => player.status !== "left").map((player) => player.id);
117	  /** Mostly a player still in the match; sometimes one who left, or an unknown id. */
118	  const anyPlayer = () => {
119	    const roll = dice.int(100);
120	    if (roll < 88 && present().length > 0) return dice.pick(present());
121	    if (roll < 97 && players().length > 0) return dice.pick(players());
122	    return "ghost";
123	  };
124	  const idle = () => present().filter((id) => activeDuelOf(state, id) === undefined);
125	  const position = () => ({ x: dice.int(50_000), y: dice.int(50_000) });
126	
127	  /** A run of world ticks: the clock advances and each channelling player holds on, now and then letting go a tick. */
128	  const ticks = () => {
129	    for (let burst = 1 + dice.int(20); burst > 0; burst--) {
130	      now += 1;
131	      // The room advances every tick; here only when a choice window is due, or at random, to keep the test quick.
132	      const due = state.duels.some((duel) => duel.phase === "choosing" && duel.choiceDeadline! <= now);
133	      if (due || dice.percent(10)) {
134	        const advanced = apply("advance", advanceLedger, { tick: now });
135	        for (const duel of advanced.settled) count(`default-theft:${duel.settlement!.stolenType === null ? "none" : "type"}`);
136	      }
137	      for (const player of state.players) {
138	        if (player.channel !== null && !dice.percent(0.3)) {
139	          const progress = apply("progress", progressChannel, { playerId: player.id, tick: now });
140	          if (progress.status === "claimed" || progress.status === "collected") {
141	            expect(findRubbing(state, progress.rubbingId!)!.location).toEqual({ kind: "player", playerId: player.id });
142	          }
143	        }
144	      }
145	    }
146	  };
147	
148	  const actions: [number, () => void][] = [
149	    [40, ticks],
150	    [1, () => {
151	      now += 1 + dice.int(1500);
152	      apply("advance", advanceLedger, { tick: now });
153	    }],
154	    [3, () => {
155	      const fresh = present().length < maxPlayers && dice.percent(90);
156	      apply("join", addPlayer, { playerId: fresh ? `p${++joined}` : anyPlayer(), tick: now, gold: dice.percent(20) ? dice.int(400) : undefined });
157	    }],
158	    [4, () => {
159	      const playerId = anyPlayer();
160	      const held = new Set(findPlayer(state, playerId) ? heldTypes(state, playerId) : []);
161	      const sealed = state.sources.filter((source) => findRubbing(state, source.rubbingId)!.location.kind === "source");
162	      const useful = sealed.filter((source) => !held.has(source.type));
163	      const already = sealed.filter((source) => held.has(source.type));
164	      const roll = dice.int(100);
165	      const source =
166	        roll < 65 && useful.length > 0 ? dice.pick(useful) : roll < 80 && already.length > 0 ? dice.pick(already) : dice.pick(state.sources);
167	      apply("start-collect", startCollect, { playerId, sourceId: dice.percent(97) ? source.id : "source-99-9", tick: now });
168	    }],
169	    [4, () => {
170	      const playerId = anyPlayer();
171	      if (state.caches.length === 0) return;
172	      const cache = dice.pick(state.caches);
173	      const held = new Set(findPlayer(state, playerId) ? heldTypes(state, playerId) : []);
174	      const inside = cacheRubbings(state, cache.id);
175	      const wanted = inside.filter((rubbing) => !held.has(rubbing.type));
176	      const rubbing = dice.percent(80) && wanted.length > 0 ? dice.pick(wanted) : dice.pick(state.rubbings);
177	      apply("start-claim", startCacheClaim, { playerId, cacheId: cache.id, rubbingId: rubbing.id, tick: now });
178	    }],
179	    [1, () => apply("cancel", cancelChannel, { playerId: anyPlayer(), tick: now })],
180	    [2, () => {
181	      // A rival starts on the same rubbing someone is already channelling: only one of them may get it.
182	      const channelling = state.players.filter((player) => player.channel !== null);
183	      const rivals = idle().filter((id) => findPlayer(state, id)!.status === "connected" && findPlayer(state, id)!.channel === null);
184	      if (channelling.length === 0 || rivals.length === 0) return;
185	      const channel = dice.pick(channelling).channel!;
186	      const playerId = dice.pick(rivals);
187	      if (channel.kind === "collect") apply("contest-collect", startCollect, { playerId, sourceId: channel.sourceId, tick: now });
188	      else apply("contest-claim", startCacheClaim, { playerId, cacheId: channel.cacheId, rubbingId: channel.rubbingId, tick: now });
189	    }],
190	    [4, () => {
191	      if (players().length < 2) return;
192	      const reuse = dice.percent(5) && duelNumber > 0;
193	      const duelId = reuse ? `d${1 + dice.int(duelNumber)}` : `d${++duelNumber}`;
194	      const free = idle();
195	      const pair = free.length >= 2 && dice.percent(85) ? [dice.pick(free), dice.pick(free)] : [anyPlayer(), anyPlayer()];
196	      const request = { duelId, players: [pair[0]!, pair[1]!] as const, tick: now };
197	      apply("reserve", reserveDuel, request);
198	      messages.push(() => reserveDuel(state, { ...request, tick: now }));
199	    }],
200	    [4, () => {
201	      const open = state.duels.filter((duel) => duel.phase === "fighting");
202	      const duel = dice.percent(90) && open.length > 0 ? dice.pick(open) : state.duels.length > 0 ? dice.pick(state.duels) : undefined;
203	      if (!duel) return;
204	      const roll = dice.int(100);
205	      const request =
206	        roll < 75
207	          ? { duelId: duel.id, tick: now, outcome: "win" as const, winner: dice.percent(95) ? dice.pick(duel.players) : anyPlayer() }
208	          : roll < 95
209	            ? { duelId: duel.id, tick: now, outcome: "draw" as const }
210	            : { duelId: duel.id, tick: now, outcome: "cancelled" as const };
211	      const result = apply("result", reportDuelResult, request);
212	      if (result.ok && result.duel!.phase === "settled" && request.outcome === "win") count("settled-without-choice");
213	      messages.push(() => reportDuelResult(state, { ...request, tick: now }));
214	    }],
215	    [4, () => {
216	      const choosing = state.duels.filter((duel) => duel.phase === "choosing");
217	      if (choosing.length === 0) return;
218	      const duel = dice.pick(choosing);
219	      const eligible = eligibleTheftTypes(state, duel.id);
220	      const type = dice.percent(80) && eligible.length > 0 ? dice.pick(eligible) : dice.pick(state.types);
221	      const playerId = dice.percent(80) ? duel.result!.winner! : dice.pick(duel.players);
222	      const request = { duelId: duel.id, playerId, type, tick: now };
223	      const result = apply("choose", chooseTheft, request);
224	      if (result.ok) count(`chosen-theft:${result.duel!.settlement!.stolenType === null ? "none" : "type"}`);
225	      messages.push(() => chooseTheft(state, { ...request, tick: now }));
226	    }],
227	    [3, () => {
228	      if (messages.length === 0) return;
229	      const replay = dice.pick(messages);
230	      const before = state;
231	      const { state: after, result } = replay();
232	      count("operations");
233	      count(`repeat:${result.ok ? "ok" : result.rejection}`);
234	      if (check) {
235	        expect(checkLedger(after)).toEqual([]);
236	        if (!result.ok) expect(after).toBe(before);
237	      }
238	      state = check ? deepFreeze(after) : after;
239	    }],
240	    [2, () => apply("disconnect", disconnectPlayer, { playerId: anyPlayer(), tick: now })],
241	    [2, () => apply("reconnect", reconnectPlayer, { playerId: anyPlayer(), tick: now })],
242	    [2, () => {
243	      const waiting = state.players.filter((player) => player.status === "disconnected");
244	      const target = waiting.length > 0 && dice.percent(80) ? dice.pick(waiting) : undefined;
245	      if (target && dice.percent(60)) now = Math.max(now, target.reservationDeadline!);
246	      const result = apply("expire", expireReservation, { playerId: target?.id ?? anyPlayer(), tick: now, position: position() });
247	      if (result.ok && result.duel) count("expire-in-duel");
248	    }],
249	    [1, () => {
250	      const result = apply("quit", quitPlayer, { playerId: anyPlayer(), tick: now, position: position() });
251	      if (result.ok && result.duel) count(`quit-in-duel:${result.duel.phase}`);
252	    }],
253	    [2, () => apply("unlock", unlockSource, { sourceId: dice.pick(state.sources).id, tick: now })],
254	    [1, () => {
255	      if (state.tick === 0) return;
256	      const stale = state.tick - 1 - dice.int(Math.min(state.tick, 20));
257	      const result = apply("stale", addPlayer, { playerId: `late${stale}`, tick: stale });
258	      expect(result.rejection).toBe("stale-tick");
259	    }],
260	  ];
261	  const total = actions.reduce((sum, [weight]) => sum + weight, 0);
262	
263	  for (let step = 0; step < steps; step++) {
264	    let roll = dice.int(total);
265	    const action = actions.find(([weight]) => (roll -= weight) < 0)!;
266	    action[1]();
267	  }
268	  for (const duel of state.duels) {
269	    if (duel.settlement?.goldSuppressed) count("gold-suppressed");
270	    if (duel.result?.forfeit) count("forfeit");
271	    if (duel.settlement?.stolenRubbingId !== null && duel.settlement?.stolenRubbingId !== undefined) count("theft");
272	    if (duel.result?.outcome === "win" && duel.settlement?.stolenRubbingId === null) count("win-without-theft");
273	  }
274	  stats.caches = state.nextCacheNumber - 1;
275	  stats.rumors = state.players.filter((player) => player.freshRumors.length > 0).length;
276	  return { state, stats };
277	}
278	
279	const SEEDS = [1, 2, 3];
280	const STEPS = 1200;
281	
282	/** Each rule the sequences exercise, by the stats that show it happened (any of them). */
283	const EXERCISED: [string, string[]][] = [
284	  ["collection", ["status:collected"]],
285	  ["cache claim", ["status:claimed"]],
286	  ["contested completion fails", ["status:failed"]],
287	  ["interrupted hold resets", ["status:reset"]],
288	  ["cancelled hold", ["status:cancelled"]],
289	  ["held type refused", ["start-collect:type-held", "start-claim:type-held", "contest-collect:type-held", "contest-claim:type-held"]],
290	  ["winner's theft choice", ["chosen-theft:type"]],
291	  ["default theft at the deadline", ["default-theft:type"]],
292	  ["win with no eligible type", ["settled-without-choice"]],
293	  ["refused choice", ["choose:ineligible-type", "choose:not-winner", "choose:choice-window-closed"]],
294	  ["draw or win recorded", ["result:ok"]],
295	  ["repeated result", ["result:already-resolved", "repeat:already-resolved"]],
